12: export function getLocalDateString(date: Date, timezone: string = 'UTC'): LocalDateString {
13:   // Use Intl.DateTimeFormat with en-CA which outputs YYYY-MM-DD format
14:   const formatter = new Intl.DateTimeFormat('en-CA', {
15:     timeZone: timezone,
16:     year: 'numeric',
17:     month: '2-digit',
18:     day: '2-digit',
19:   });
20:   return formatter.format(date);
21: }
22: 
23: /**
24:  * Resolves which logical Day a given timestamp belongs to.
25:  * Follows the wake-to-sleep boundary paradigm:
26:  * If an active day is currently ongoing (wakeAt <= timestamp and sleepAt is either not set or timestamp <= sleepAt),
27:  * then even if the timestamp is past local midnight (e.g., 01:30 AM), it belongs to that ongoing logical Day.
28:  */
29: export function resolveLogicalDay(
30:   timestamp: Date | ISODateTimeString,
31:   timezone: string = 'UTC',
32:   activeDay?: DayWindow
33: ): LocalDateString {
34:   const dateObj = typeof timestamp === 'string' ? new Date(timestamp) : timestamp;
35: 
36:   if (activeDay?.wakeAt) {
37:     const wakeTime = new Date(activeDay.wakeAt).getTime();
38:     const eventTime = dateObj.getTime();
39: 
40:     if (eventTime >= wakeTime) {
41:       if (!activeDay.sleepAt) {
42:         // Still awake, belongs to active day
43:         return activeDay.localDate;
44:       }
45:       const sleepTime = new Date(activeDay.sleepAt).getTime();
46:       if (eventTime <= sleepTime) {
47:         return activeDay.localDate;
48:       }
49:     }
50:   }
51: 
52:   // Fallback to local calendar date in the specified timezone
53:   return getLocalDateString(dateObj, timezone);
54: }

