3: /**
4:  * Resolves a sync conflict between a local entity and an incoming entity using Last-Write-Wins (LWW).
5:  * 
6:  * Rules:
7:  * 1. The entity with the later `updatedAt` timestamp strictly wins.
8:  * 2. If `updatedAt` timestamps are identical:
9:  *    - If one has `isDeleted = true` and the other does not, deletion wins for safety.
10:  *    - Otherwise, incoming entity is preferred deterministically.
11:  */
12: export function resolveLWW<T extends EntityMetadata>(local: T, incoming: T): { winner: T; isUpdated: boolean } {
13:   const localTime = new Date(local.updatedAt).getTime();
14:   const incomingTime = new Date(incoming.updatedAt).getTime();
15: 
16:   if (incomingTime > localTime) {
17:     return { winner: incoming, isUpdated: true };
18:   }
19: 
20:   if (incomingTime < localTime) {
21:     return { winner: local, isUpdated: false };
22:   }
23: 
24:   // Identical timestamps tie-breaker
25:   if (incoming.isDeleted && !local.isDeleted) {
26:     return { winner: incoming, isUpdated: true };
27:   }
28: 
29:   if (!incoming.isDeleted && local.isDeleted) {
30:     return { winner: local, isUpdated: false };
31:   }
32: 
33:   // Pure identical tie: take incoming
34:   return { winner: incoming, isUpdated: true };
35: }

