17:   private outbox: Map<string, OutboxItem> = new Map();
18: 
19:   async saveMarkerAndEnqueueOutbox(marker: Marker): Promise<{ saveDurationMs: number }> {
20:     const start = performance.now();
21: 
22:     // 1. Save to local store
23:     this.markers.set(marker.id, marker);
24: 
25:     // 2. Enqueue to outbox atomically
26:     const outboxId = `outbox-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
27:     const outboxItem = createOutboxItem(
28:       outboxId,
29:       'marker',
30:       marker.id,
31:       'UPSERT',
32:       marker,
33:       marker.updatedAt,
34:       marker.isDeleted
35:     );
36:     this.outbox.set(outboxId, outboxItem);
37: 
38:     const saveDurationMs = performance.now() - start;
39:     return { saveDurationMs };
40:   }
41: 
42:   async getPendingOutboxItems(): Promise<OutboxItem[]> {
43:     return Array.from(this.outbox.values()).filter((item) => item.status === 'PENDING');
