import { Day, Event, ISODateTimeString } from './types.js';

export interface VisualTimelineEvent {
  event: Event;
  laneIndex: number;
  totalLanes: number;
}

export interface TimelineGap {
  startAt: ISODateTimeString;
  endAt: ISODateTimeString;
  durationMinutes: number;
}

export interface TimeInterval {
  startMs: number;
  endMs: number;
}

/**
 * Returns the absolute [start, end] interval for an event. A point-in-time
 * event (no endAt) has an end equal to its start.
 */
export function getEventInterval(event: Event): TimeInterval {
  const startMs = new Date(event.startAt).getTime();
  const endMs = event.endAt ? new Date(event.endAt).getTime() : startMs;
  return { startMs, endMs: Math.max(startMs, endMs) };
}

/**
 * Merges overlapping or touching intervals into a flat, sorted busy list.
 * Optionally clips intervals to a window.
 */
export function mergeIntervals(
  intervals: TimeInterval[],
  windowStartMs?: number,
  windowEndMs?: number
): TimeInterval[] {
  const clipped: TimeInterval[] = [];

  for (const interval of intervals) {
    let start = interval.startMs;
    let end = interval.endMs;

    if (!Number.isFinite(start) || !Number.isFinite(end)) continue;
    if (end < start) [start, end] = [end, start];

    if (windowStartMs !== undefined) start = Math.max(start, windowStartMs);
    if (windowEndMs !== undefined) end = Math.min(end, windowEndMs);
    if (end < start) continue;

    clipped.push({ startMs: start, endMs: end });
  }

  clipped.sort((a, b) => a.startMs - b.startMs || a.endMs - b.endMs);

  const merged: TimeInterval[] = [];
  for (const interval of clipped) {
    const last = merged[merged.length - 1];
    if (!last || interval.startMs > last.endMs) {
      merged.push({ ...interval });
    } else if (interval.endMs > last.endMs) {
      last.endMs = interval.endMs;
    }
  }

  return merged;
}

/**
 * Total non-overlapping duration covered by the supplied events.
 * Overlapping events are only counted once.
 */
export function calculateUnionDuration(
  events: Event[],
  windowStartMs?: number,
  windowEndMs?: number
): number {
  const merged = mergeIntervals(events.map(getEventInterval), windowStartMs, windowEndMs);
  return merged.reduce((total, interval) => total + (interval.endMs - interval.startMs), 0);
}

/**
 * Assigns visual lanes to interval events using greedy interval graph colouring.
 * Lanes are derived, never stored. Events that overlap are rendered side by side.
 */
export function computeTimelineLanes(events: Event[]): VisualTimelineEvent[] {
  const sorted = [...events].sort((a, b) => {
    const aStart = new Date(a.startAt).getTime();
    const bStart = new Date(b.startAt).getTime();
    if (aStart !== bStart) return aStart - bStart;

    const aEnd = a.endAt ? new Date(a.endAt).getTime() : aStart;
    const bEnd = b.endAt ? new Date(b.endAt).getTime() : bStart;
    return bEnd - aEnd;
  });

  const laneEnds: number[] = [];
  const assigned: Array<{ event: Event; laneIndex: number; startMs: number; endMs: number }> = [];

  for (const event of sorted) {
    const { startMs, endMs } = getEventInterval(event);
    let laneIndex = laneEnds.findIndex((laneEnd) => laneEnd <= startMs);
    if (laneIndex === -1) {
      laneIndex = laneEnds.length;
      laneEnds.push(endMs);
    } else {
      laneEnds[laneIndex] = endMs;
    }

    assigned.push({ event, laneIndex, startMs, endMs });
  }

  // Compute totalLanes per connected overlap cluster so isolated events stay
  // full-width even if another part of the day uses multiple lanes.
  const result: VisualTimelineEvent[] = [];
  let clusterStart = 0;

  while (clusterStart < assigned.length) {
    let clusterEnd = clusterStart;
    let maxEnd = assigned[clusterStart].endMs;
    let maxLane = assigned[clusterStart].laneIndex;

    while (clusterEnd + 1 < assigned.length && assigned[clusterEnd + 1].startMs <= maxEnd) {
      clusterEnd++;
      maxEnd = Math.max(maxEnd, assigned[clusterEnd].endMs);
      maxLane = Math.max(maxLane, assigned[clusterEnd].laneIndex);
    }

    const totalLanes = maxLane + 1;
    for (let i = clusterStart; i <= clusterEnd; i++) {
      result.push({
        event: assigned[i].event,
        laneIndex: assigned[i].laneIndex,
        totalLanes,
      });
    }

    clusterStart = clusterEnd + 1;
  }

  return result;
}

/**
 * Finds unlogged gaps between wake and sleep (or now, when still awake).
 * Only gaps at least minGapMinutes long are surfaced.
 */
export function findTimelineGaps(
  day: Day,
  events: Event[],
  minGapMinutes: number = 15,
  currentTime: Date = new Date()
): TimelineGap[] {
  if (!day.wakeAt) return [];

  const wakeMs = new Date(day.wakeAt).getTime();
  if (!Number.isFinite(wakeMs)) return [];

  const endMs = day.sleepAt ? new Date(day.sleepAt).getTime() : currentTime.getTime();
  if (!Number.isFinite(endMs) || endMs <= wakeMs) return [];

  const busy = mergeIntervals(events.map(getEventInterval), wakeMs, endMs);
  const minGapMs = Math.max(0, minGapMinutes) * 60_000;
  const gaps: TimelineGap[] = [];

  let cursor = wakeMs;
  for (const interval of busy) {
    if (interval.startMs - cursor >= minGapMs) {
      gaps.push(toGap(cursor, interval.startMs));
    }
    cursor = Math.max(cursor, interval.endMs);
  }

  if (endMs - cursor >= minGapMs) {
    gaps.push(toGap(cursor, endMs));
  }

  return gaps;
}

function toGap(startMs: number, endMs: number): TimelineGap {
  return {
    startAt: new Date(startMs).toISOString(),
    endAt: new Date(endMs).toISOString(),
    durationMinutes: Math.round(((endMs - startMs) / 60_000) * 100) / 100,
  };
}

import {
  Day,
  DayFidelity,
  Event,
  ISODateTimeString,
  JournalEntry,
} from './types.js';
import { calculateUnionDuration } from './timeline.js';

export interface DayLifecycleOptions {
  now?: Date;
}

function cloneWith(day: Day, patch: Partial<Day>, now: Date): Day {
  return {
    ...day,
    ...patch,
    updatedAt: now.toISOString(),
  };
}

/**
 * Records the start of a logical day. Re-waking an already-open day is
 * idempotent and keeps the existing wake time.
 */
export function wakeDay(
  day: Day,
  wakeAt: ISODateTimeString,
  options: DayLifecycleOptions = {}
): Day {
  const now = options.now ?? new Date();
  if (day.wakeAt) return day;
  return cloneWith(day, { wakeAt, updatedAt: now.toISOString() }, now);
}

/**
 * Records the end of a logical day (sleep). This does not mark the day's
 * evening review complete; see completeDayReview().
 */
export function sleepDay(
  day: Day,
  sleepAt: ISODateTimeString,
  options: DayLifecycleOptions = {}
): Day {
  const now = options.now ?? new Date();
  return cloneWith(day, { sleepAt }, now);
}

export function beginDayReview(day: Day, options: DayLifecycleOptions = {}): Day {
  const now = options.now ?? new Date();
  return cloneWith(day, { reviewStatus: 'in_progress' }, now);
}

export function skipDayReview(day: Day, options: DayLifecycleOptions = {}): Day {
  const now = options.now ?? new Date();
  return cloneWith(day, { reviewStatus: 'skipped' }, now);
}

export interface CompleteDayReviewOptions extends DayLifecycleOptions {
  sleepAt?: ISODateTimeString;
}

/**
 * Closes the daily loop: stores sleep when supplied, derives fidelity and
 * marks the review complete. Fidelity is always derived, never asked for.
 */
export function completeDayReview(
  day: Day,
  events: Event[],
  journalEntries: JournalEntry[],
  options: CompleteDayReviewOptions = {}
): Day {
  const now = options.now ?? new Date();
  const sleepAt = options.sleepAt ?? day.sleepAt;
  const withSleep = sleepAt ? { ...day, sleepAt } : day;
  const fidelity = calculateDayFidelity(withSleep, events, journalEntries, now);

  return cloneWith(
    withSleep,
    { reviewStatus: 'completed', fidelity },
    now
  );
}

/**
 * Determines Day.fidelity from timeline coverage plus journal presence:
 * - detailed: >= 75% waking coverage AND a non-empty journal entry
 * - summary:  >= 30% waking coverage OR a non-empty journal entry
 * - skipped:  neither
 */
export function calculateDayFidelity(
  day: Day,
  events: Event[],
  journalEntries: JournalEntry[],
  currentTime: Date = new Date()
): DayFidelity {
  if (!day.wakeAt) return 'skipped';

  const wakeMs = new Date(day.wakeAt).getTime();
  if (!Number.isFinite(wakeMs)) return 'skipped';

  const endMs = day.sleepAt ? new Date(day.sleepAt).getTime() : currentTime.getTime();
  if (!Number.isFinite(endMs) || endMs <= wakeMs) return 'skipped';

  const wakingDurationMs = endMs - wakeMs;
  const coveredMs = calculateUnionDuration(events, wakeMs, endMs);
  const coverageRatio = coveredMs / wakingDurationMs;
  const hasJournal =
    journalEntries.length > 0 && journalEntries.some((entry) => entry.body.trim().length > 0);

  if (coverageRatio >= 0.75 && hasJournal) return 'detailed';
  if (coverageRatio >= 0.3 || hasJournal) return 'summary';
  return 'skipped';
}

/**
 * Returns coverage as a 0..1 ratio for display in the review UI.
 */
export function calculateDayCoverage(
  day: Day,
  events: Event[],
  currentTime: Date = new Date()
): number {
  if (!day.wakeAt) return 0;

  const wakeMs = new Date(day.wakeAt).getTime();
  const endMs = day.sleepAt ? new Date(day.sleepAt).getTime() : currentTime.getTime();
  if (!Number.isFinite(wakeMs) || !Number.isFinite(endMs) || endMs <= wakeMs) return 0;

  return Math.min(1, calculateUnionDuration(events, wakeMs, endMs) / (endMs - wakeMs));
}

import { EventTag, Tag, UUID } from './types.js';

export interface TagNode {
  tag: Tag;
  children: TagNode[];
}

/**
 * Normalizes a free-form tag into the canonical slash-separated path form.
 * Examples: " #Work/Coding " -> "work/coding", "food & drink" -> "food-drink".
 */
export function normalizeTagPath(raw: string): string {
  return raw
    .trim()
    .replace(/^#+/, '')
    .split('/')
    .map((segment) =>
      segment
        .trim()
        .toLowerCase()
        .replace(/\s+/g, '-')
        .replace(/[^a-z0-9_-]/g, '')
        .replace(/-+/g, '-')
        .replace(/^-|-$/g, '')
    )
    .filter((segment) => segment.length > 0)
    .join('/');
}

export function tagNameFromPath(path: string): string {
  const segments = normalizeTagPath(path).split('/').filter(Boolean);
  const name = segments[segments.length - 1] ?? '';
  return name.replace(/[-_]+/g, ' ').replace(/\b\w/g, (char) => char.toUpperCase());
}

export function tagParentPath(path: string): string | undefined {
  const segments = normalizeTagPath(path).split('/').filter(Boolean);
  return segments.length > 1 ? segments.slice(0, -1).join('/') : undefined;
}

/**
 * Builds a stable hierarchy from a flat tag list. Orphans are attached at the
 * root so bad incoming data can never break the tree.
 */
export function buildTagTree(tags: Tag[]): TagNode[] {
  const active = tags.filter((tag) => !tag.isDeleted);
  const byId = new Map<UUID, TagNode>();
  for (const tag of active) {
    byId.set(tag.id, { tag, children: [] });
  }

  const roots: TagNode[] = [];
  for (const tag of active) {
    const node = byId.get(tag.id)!;
    const parent = tag.parentId ? byId.get(tag.parentId) : undefined;
    if (parent) parent.children.push(node);
    else roots.push(node);
  }

  const sortNodes = (nodes: TagNode[]): void => {
    nodes.sort((a, b) => a.tag.path.localeCompare(b.tag.path));
    for (const node of nodes) sortNodes(node.children);
  };
  sortNodes(roots);

  return roots;
}

export interface ResolveTagsOptions {
  now?: Date;
  makeId?: (path: string) => string;
}

export interface ResolvedTagsForEvent {
  /** Existing and newly-created tags (including implicit ancestors). */
  tags: Tag[];
  eventTags: EventTag[];
  primaryTag?: Tag;
}

function defaultTagId(path: string): string {
  return `tag-${path.replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`;
}

/**
 * Turns parser tag paths into persisted Tag records (creating missing
 * ancestors) plus event-tag links. The first requested tag is primary.
 */
export function resolveTagsForEvent(
  eventId: UUID,
  tagPaths: string[],
  existingTags: Tag[],
  options: ResolveTagsOptions = {}
): ResolvedTagsForEvent {
  const now = options.now ?? new Date();
  const makeId = options.makeId ?? defaultTagId;
  const known = new Map<string, Tag>();
  for (const tag of existingTags) {
    if (!tag.isDeleted) known.set(tag.path, tag);
  }

  const requested = Array.from(
    new Set(tagPaths.map(normalizeTagPath).filter((path) => path.length > 0))
  );

  const allPaths = new Set<string>();
  for (const path of requested) {
    const segments = path.split('/');
    for (let i = 1; i <= segments.length; i++) {
      allPaths.add(segments.slice(0, i).join('/'));
    }
  }

  const created: Tag[] = [];
  const orderedPaths = Array.from(allPaths).sort((a, b) => a.split('/').length - b.split('/').length || a.localeCompare(b));
  for (const path of orderedPaths) {
    if (known.has(path)) continue;

    const parentPath = tagParentPath(path);
    const parent = parentPath ? known.get(parentPath) : undefined;
    const tag: Tag = {
      id: makeId(path),
      name: tagNameFromPath(path),
      path,
      parentId: parent?.id,
      createdAt: now.toISOString(),
      updatedAt: now.toISOString(),
      isDeleted: false,
    };
    known.set(path, tag);
    created.push(tag);
  }

  const requestedTags = requested
    .map((path) => known.get(path))
    .filter((tag): tag is Tag => Boolean(tag));

  const eventTags: EventTag[] = requestedTags.map((tag, index) => ({
    eventId,
    tagId: tag.id,
    isPrimary: index === 0,
  }));

  return {
    tags: created,
    eventTags,
    primaryTag: requestedTags[0],
  };
}

import { EventParticipant, Person, UUID } from './types.js';

export function normalizePersonName(name: string): string {
  return name.trim().replace(/^@+/, '').replace(/\s+/g, ' ').toLowerCase();
}

export function findPersonByNameOrAlias(
  people: Person[],
  name: string
): Person | undefined {
  const needle = normalizePersonName(name);
  if (!needle) return undefined;

  return people.find((person) => {
    if (person.isDeleted) return false;
    if (normalizePersonName(person.displayName) === needle) return true;
    return person.aliases.some((alias) => normalizePersonName(alias) === needle);
  });
}

export interface ResolvePeopleOptions {
  now?: Date;
  makeId?: (normalized: string) => string;
  role?: string;
}

export interface ResolvedPeopleForEvent {
  people: Person[];
  participants: EventParticipant[];
}

function defaultPersonId(name: string): string {
  return `person-${name.replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`;
}

/**
 * Resolves @mentions to existing people (by display name or alias), creating
 * a minimal Person for genuinely new names. Matching is case-insensitive.
 */
export function resolvePeopleForEvent(
  eventId: UUID,
  names: string[],
  existingPeople: Person[],
  options: ResolvePeopleOptions = {}
): ResolvedPeopleForEvent {
  const now = options.now ?? new Date();
  const makeId = options.makeId ?? defaultPersonId;
  const known = [...existingPeople.filter((person) => !person.isDeleted)];
  const created: Person[] = [];
  const participants: EventParticipant[] = [];
  const seen = new Set<string>();

  for (const rawName of names) {
    const displayName = rawName.trim().replace(/^@+/, '').replace(/\s+/g, ' ');
    const normalized = normalizePersonName(displayName);
    if (!normalized || seen.has(normalized)) continue;
    seen.add(normalized);

    let person = findPersonByNameOrAlias(known, normalized);
    if (!person) {
      person = {
        id: makeId(normalized),
        displayName,
        aliases: [],
        createdAt: now.toISOString(),
        updatedAt: now.toISOString(),
        isDeleted: false,
      };
      known.push(person);
      created.push(person);
    }

    participants.push({
      eventId,
      personId: person.id,
      role: options.role ?? 'with',
      medium: 'in_person',
      initiatedBy: 'mutual',
    });
  }

  return { people: created, participants };
}

import {
  CaptureSource,
  Event,
  ISODateTimeString,
  Precision,
  UUID,
} from './types.js';
import { normalizeTagPath } from './tags.js';
import { normalizePersonName } from './people.js';

export const QUICK_ENTRY_PARSER_VERSION = 'rule-parser-v0';

export interface ParsedQuickEntry {
  rawText: string;
  title: string;
  startAt: ISODateTimeString;
  endAt?: ISODateTimeString;
  startPrecision: Precision;
  endPrecision: Precision;
  tagPaths: string[];
  primaryTagPath?: string;
  peopleNames: string[];
  durationMinutes?: number;
  parsedBy: typeof QUICK_ENTRY_PARSER_VERSION;
  /** Whether a time token was explicitly present in the input. */
  hasExplicitTime: boolean;
}

interface ParsedTime {
  hours: number;
  minutes: number;
}

const TIME_ATOM = String.raw`(?:\d{1,2}(?::\d{2})?\s*(?:am|pm)?|noon|midnight)`;
const TIME_ATOM_MARKED = String.raw`(?:\d{1,2}:\d{2}\s*(?:am|pm)?|\d{1,2}\s*(?:am|pm)|noon|midnight)`;

function tagRegex(): RegExp {
  return /#([\p{L}\p{N}][\p{L}\p{N}_/-]*)/gu;
}

function mentionRegex(): RegExp {
  return /@([\p{L}\p{N}][\p{L}\p{N}._-]*)/gu;
}

function rangeRegex(): RegExp {
  const withConnector = String.raw`(?:\bfrom\s+|\bat\s+)?(${TIME_ATOM})\s*(?:to|until|till)\s*(${TIME_ATOM})\b`;
  const withDash = String.raw`(${TIME_ATOM_MARKED})\s*[-–—]\s*(${TIME_ATOM_MARKED})\b`;
  return new RegExp(`${withConnector}|${withDash}`, 'i');
}

function durationRegex(): RegExp {
  return /\bfor\s+(\d+(?:\.\d+)?\s*(?:hours?|hrs?|h|minutes?|mins?|m)(?:\s*\d+\s*(?:minutes?|mins?|m))?)/i;
}

function pointTimeRegex(): RegExp {
  return /\b(?:at\s+)?(\d{1,2}(?::\d{2})?\s*(?:am|pm)|noon|midnight)\b|\bat\s+(\d{1,2})\b/i;
}

function parseTime(raw: string): ParsedTime | null {
  const value = raw.trim().toLowerCase().replace(/\s+/g, '');
  if (!value) return null;
  if (value === 'noon') return { hours: 12, minutes: 0 };
  if (value === 'midnight') return { hours: 0, minutes: 0 };

  const match = /^(\d{1,2})(?::(\d{2}))?(am|pm)?$/.exec(value);
  if (!match) return null;

  let hours = Number(match[1]);
  const minutes = match[2] ? Number(match[2]) : 0;
  const meridiem = match[3];

  if (!Number.isInteger(hours) || minutes < 0 || minutes > 59) return null;

  if (meridiem) {
    if (hours < 1 || hours > 12) return null;
    if (meridiem === 'pm' && hours < 12) hours += 12;
    if (meridiem === 'am' && hours === 12) hours = 0;
  } else if (hours > 23) {
    return null;
  }

  return { hours, minutes };
}

function parseDurationMinutes(raw: string): number | null {
  const value = raw.toLowerCase().replace(/\s+/g, '');
  const hourMatch = /(\d+(?:\.\d+)?)h(?:ours?|rs?)?/.exec(value);
  const minuteMatch = /(\d+)m(?:in(?:ute)?s?)?/.exec(value);

  let minutes = 0;
  let matched = false;
  if (hourMatch) {
    minutes += Number(hourMatch[1]) * 60;
    matched = true;
  }
  if (minuteMatch) {
    minutes += Number(minuteMatch[1]);
    matched = true;
  }

  if (!matched) {
    // A lone unit such as "90 min" is captured without the h prefix.
    const loneMinutes = /^(\d+)m(?:in(?:ute)?s?)?$/.exec(value);
    if (loneMinutes) return Number(loneMinutes[1]);
    return null;
  }

  return Math.round(minutes);
}

function atLocalTime(now: Date, time: ParsedTime, dayOffset: number = 0): Date {
  const result = new Date(
    now.getFullYear(),
    now.getMonth(),
    now.getDate() + dayOffset,
    time.hours,
    time.minutes,
    0,
    0
  );
  return result;
}

function cleanTitle(input: string, fallback: string): string {
  const cleaned = input
    .replace(/\s+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/^[\s,;:–—-]+/, '')
    .replace(/[\s,;:–—-]+$/, '')
    .replace(/^(?:at|from|for|to)\s+/i, '')
    .trim();

  return cleaned.length > 0 ? cleaned : fallback;
}

/**
 * Deterministic rule-based quick-entry parser. Never throws, never invents a
 * time or title, and leaves unrecognised text in the title untouched.
 */
export function parseQuickEntry(rawText: string, now: Date = new Date()): ParsedQuickEntry {
  const raw = typeof rawText === 'string' ? rawText : '';
  let working = raw;
  const tagPaths: string[] = [];
  const peopleNames: string[] = [];

  working = working.replace(tagRegex(), (_match, path: string) => {
    const normalized = normalizeTagPath(path);
    if (normalized && !tagPaths.includes(normalized)) tagPaths.push(normalized);
    return ' ';
  });

  working = working.replace(mentionRegex(), (_match, name: string) => {
    const cleaned = name.replace(/[.,;:!?]+$/, '');
    const normalized = normalizePersonName(cleaned);
    if (normalized && !peopleNames.some((existing) => normalizePersonName(existing) === normalized)) {
      peopleNames.push(cleaned);
    }
    return ' ';
  });

  let durationMinutes: number | undefined;
  const durationMatch = durationRegex().exec(working);
  if (durationMatch) {
    const parsedDuration = parseDurationMinutes(durationMatch[1]);
    if (parsedDuration !== null && parsedDuration > 0) {
      durationMinutes = parsedDuration;
    }
    working = working.replace(durationMatch[0], ' ');
  }

  let startAt: Date | null = null;
  let endAt: Date | null = null;
  let hasExplicitTime = false;

  const rangeMatch = rangeRegex().exec(working);
  if (rangeMatch) {
    const startRaw = rangeMatch[1] ?? rangeMatch[3];
    const endRaw = rangeMatch[2] ?? rangeMatch[4];
    const startTime = startRaw ? parseTime(startRaw) : null;
    const endTime = endRaw ? parseTime(endRaw) : null;

    if (startTime && endTime) {
      startAt = atLocalTime(now, startTime);
      endAt = atLocalTime(now, endTime);
      if (endAt.getTime() <= startAt.getTime()) {
        endAt = atLocalTime(now, endTime, 1);
      }
      hasExplicitTime = true;
      working = working.replace(rangeMatch[0], ' ');
    }
  }

  if (!startAt) {
    const pointMatch = pointTimeRegex().exec(working);
    if (pointMatch) {
      const timeRaw = pointMatch[1] ?? pointMatch[2];
      const parsedTime = timeRaw ? parseTime(timeRaw) : null;
      if (parsedTime) {
        startAt = atLocalTime(now, parsedTime);
        hasExplicitTime = true;
        working = working.replace(pointMatch[0], ' ');
      }
    }
  }

  const finalStart = startAt ?? new Date(now.getTime());
  let finalEnd = endAt;
  if (!finalEnd && durationMinutes !== undefined) {
    finalEnd = new Date(finalStart.getTime() + durationMinutes * 60_000);
  }

  return {
    rawText: raw,
    title: cleanTitle(working, raw.trim()),
    startAt: finalStart.toISOString(),
    endAt: finalEnd?.toISOString(),
    startPrecision: 'exact',
    endPrecision: 'exact',
    tagPaths,
    primaryTagPath: tagPaths[0],
    peopleNames,
    durationMinutes,
    parsedBy: QUICK_ENTRY_PARSER_VERSION,
    hasExplicitTime,
  };
}

export interface BuildEventFromQuickEntryOptions {
  id: UUID;
  dayId: UUID;
  source?: CaptureSource;
  notes?: string;
  now?: Date;
}

export function buildEventFromQuickEntry(
  parsed: ParsedQuickEntry,
  options: BuildEventFromQuickEntryOptions
): Event {
  const now = options.now ?? new Date();
  const timestamp = now.toISOString();

  return {
    id: options.id,
    dayId: options.dayId,
    title: parsed.title,
    startAt: parsed.startAt,
    endAt: parsed.endAt,
    startPrecision: parsed.startPrecision,
    endPrecision: parsed.endPrecision,
    source: options.source ?? 'live',
    notes: options.notes,
    createdAt: timestamp,
    updatedAt: timestamp,
    isDeleted: false,
  };
}

