}

export interface IJournalRepository {
  save(entry: JournalEntry): Promise<void>;
  saveBatch(entries: JournalEntry[]): Promise<void>;
  findById(id: UUID): Promise<JournalEntry | null>;
  listByDay(dayId: UUID, includeDeleted?: boolean): Promise<JournalEntry[]>;
  listAll(includeDeleted?: boolean): Promise<JournalEntry[]>;
  listModifiedSince(cursor: string, limit?: number): Promise<CursorResult<JournalEntry>>;
}

export interface ICaptureRepository {
  save(capture: Capture): Promise<void>;
  findById(id: UUID): Promise<Capture | null>;
  listAll(includeDeleted?: boolean): Promise<Capture[]>;
  listModifiedSince(cursor: string, limit?: number): Promise<CursorResult<Capture>>;
}

import { DatabaseSync } from './db.js';
import {
  CaptureSource,
  Event,
  Precision,
  UUID,
} from '@life-logger/domain';
import { CursorResult, IEventRepository } from '../interfaces.js';

interface EventRow {
  id: string;
  day_id: string;
  title: string;
  start_at: string;
  end_at: string | null;
  start_precision: string;
  end_precision: string;
  source: string;
  notes: string | null;
  created_at: string;
  updated_at: string;
  is_deleted: number;
}

function rowToEvent(row: EventRow): Event {
  return {
    id: row.id,
    dayId: row.day_id,
    title: row.title,
    startAt: row.start_at,
    endAt: row.end_at ?? undefined,
    startPrecision: row.start_precision as Precision,
    endPrecision: row.end_precision as Precision,
    source: row.source as CaptureSource,
    notes: row.notes ?? undefined,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    isDeleted: row.is_deleted === 1,
  };
}

export class SqliteEventRepository implements IEventRepository {
  constructor(private readonly db: DatabaseSync) {}

  async save(event: Event): Promise<void> {
    this.db
      .prepare(`
        INSERT INTO events (
          id, day_id, title, start_at, end_at, start_precision, end_precision,
          source, notes, created_at, updated_at, is_deleted
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
          day_id = excluded.day_id,
          title = excluded.title,
          start_at = excluded.start_at,
          end_at = excluded.end_at,
          start_precision = excluded.start_precision,
          end_precision = excluded.end_precision,
          source = excluded.source,
          notes = excluded.notes,
          updated_at = excluded.updated_at,
          is_deleted = excluded.is_deleted
        WHERE excluded.updated_at >= events.updated_at
      `)
      .run(
        event.id,
        event.dayId,
        event.title,
        event.startAt,
        event.endAt ?? null,
        event.startPrecision,
        event.endPrecision,
        event.source,
        event.notes ?? null,
        event.createdAt,
        event.updatedAt,
        event.isDeleted ? 1 : 0
      );
  }

  async saveBatch(events: Event[]): Promise<void> {
    if (events.length === 0) return;

    this.db.exec('BEGIN TRANSACTION');
    try {
      for (const event of events) {
        await this.save(event);
      }
      this.db.exec('COMMIT');
    } catch (err) {
      this.db.exec('ROLLBACK');
      throw err;
    }
  }

  async findById(id: UUID): Promise<Event | null> {
    const row = this.db.prepare('SELECT * FROM events WHERE id = ?').get(id) as unknown as
      | EventRow
      | undefined;
    return row ? rowToEvent(row) : null;
  }

  async listByDay(dayId: UUID, includeDeleted = false): Promise<Event[]> {
    const query = includeDeleted
      ? 'SELECT * FROM events WHERE day_id = ? ORDER BY start_at ASC, id ASC'
      : 'SELECT * FROM events WHERE day_id = ? AND is_deleted = 0 ORDER BY start_at ASC, id ASC';
    const rows = this.db.prepare(query).all(dayId) as unknown as EventRow[];
    return rows.map(rowToEvent);
  }

  async listAll(includeDeleted = false): Promise<Event[]> {
    const query = includeDeleted
      ? 'SELECT * FROM events ORDER BY start_at ASC, id ASC'
      : 'SELECT * FROM events WHERE is_deleted = 0 ORDER BY start_at ASC, id ASC';
    const rows = this.db.prepare(query).all() as unknown as EventRow[];
    return rows.map(rowToEvent);
  }

  async listModifiedSince(cursor: string = '', limit: number = 100): Promise<CursorResult<Event>> {
    const query = cursor
      ? 'SELECT * FROM events WHERE updated_at > ? ORDER BY updated_at ASC, id ASC LIMIT ?'
      : 'SELECT * FROM events ORDER BY updated_at ASC, id ASC LIMIT ?';

    const params = cursor ? [cursor, limit + 1] : [limit + 1];
    const rows = this.db.prepare(query).all(...params) as unknown as EventRow[];

    const hasMore = rows.length > limit;
    const recordsToReturn = hasMore ? rows.slice(0, limit) : rows;
    const records = recordsToReturn.map(rowToEvent);
    const nextCursor = records.length > 0 ? records[records.length - 1].updatedAt : cursor;

    return { records, nextCursor, hasMore };
  }
}

import { DatabaseSync } from './db.js';
import { EventTag, Tag, UUID } from '@life-logger/domain';
import {
  CursorResult,
  ITagRepository,
  TimestampedEventTag,
} from '../interfaces.js';

interface TagRow {
  id: string;
  name: string;
  path: string;
  color: string | null;
  parent_id: string | null;
  created_at: string;
  updated_at: string;
  is_deleted: number;
}

interface EventTagRow {
  event_id: string;
  tag_id: string;
  is_primary: number;
  updated_at?: string;
}

function rowToTag(row: TagRow): Tag {
  return {
    id: row.id,
    name: row.name,
    path: row.path,
    color: row.color ?? undefined,
    parentId: row.parent_id ?? undefined,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    isDeleted: row.is_deleted === 1,
  };
}

function rowToEventTag(row: EventTagRow): EventTag {
  return {
    eventId: row.event_id,
    tagId: row.tag_id,
    isPrimary: row.is_primary === 1,
  };
}

export class SqliteTagRepository implements ITagRepository {
  constructor(private readonly db: DatabaseSync) {}

  async save(tag: Tag): Promise<void> {
    this.db
      .prepare(`
        INSERT INTO tags (
          id, name, path, color, parent_id, created_at, updated_at, is_deleted
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
          name = excluded.name,
          path = excluded.path,
          color = excluded.color,
          parent_id = excluded.parent_id,
          updated_at = excluded.updated_at,
          is_deleted = excluded.is_deleted
        WHERE excluded.updated_at >= tags.updated_at
      `)
      .run(
        tag.id,
        tag.name,
        tag.path,
        tag.color ?? null,
        tag.parentId ?? null,
        tag.createdAt,
        tag.updatedAt,
        tag.isDeleted ? 1 : 0
      );
  }

  async saveBatch(tags: Tag[]): Promise<void> {
    if (tags.length === 0) return;

    this.db.exec('BEGIN TRANSACTION');
    try {
      for (const tag of tags) {
        await this.save(tag);
      }
      this.db.exec('COMMIT');
    } catch (err) {
      this.db.exec('ROLLBACK');
      throw err;
    }
  }

  async findById(id: UUID): Promise<Tag | null> {
    const row = this.db.prepare('SELECT * FROM tags WHERE id = ?').get(id) as unknown as
      | TagRow
      | undefined;
    return row ? rowToTag(row) : null;
  }

  async findByPath(path: string): Promise<Tag | null> {
    const row = this.db.prepare('SELECT * FROM tags WHERE path = ?').get(path) as unknown as
      | TagRow
      | undefined;
    return row ? rowToTag(row) : null;
  }

  async listTree(includeDeleted = false): Promise<Tag[]> {
    const query = includeDeleted
      ? 'SELECT * FROM tags ORDER BY path ASC'
      : 'SELECT * FROM tags WHERE is_deleted = 0 ORDER BY path ASC';
    const rows = this.db.prepare(query).all() as unknown as TagRow[];
    return rows.map(rowToTag);
  }

  async assignTagsToEvent(eventId: UUID, tags: EventTag[]): Promise<void> {
    const normalized = tags.map((tag, index) => ({
      ...tag,
      eventId,
      isPrimary: tag.isPrimary && !tags.slice(0, index).some((other) => other.isPrimary),
    }));

    this.db.exec('SAVEPOINT assign_event_tags');
    try {
      this.db.prepare('DELETE FROM event_tags WHERE event_id = ?').run(eventId);
      const insert = this.db.prepare(
        'INSERT INTO event_tags (event_id, tag_id, is_primary) VALUES (?, ?, ?)'
      );
      for (const link of normalized) {
        insert.run(eventId, link.tagId, link.isPrimary ? 1 : 0);
      }
      this.db.exec('RELEASE assign_event_tags');
    } catch (err) {
      this.db.exec('ROLLBACK TO assign_event_tags');
      this.db.exec('RELEASE assign_event_tags');
      throw err;
    }
  }

  async listEventTags(eventId: UUID): Promise<EventTag[]> {
    const rows = this.db
      .prepare('SELECT * FROM event_tags WHERE event_id = ? ORDER BY is_primary DESC, tag_id ASC')
      .all(eventId) as unknown as EventTagRow[];
    return rows.map(rowToEventTag);
  }

  async listEventTagsForDay(dayId: UUID): Promise<EventTag[]> {
    const rows = this.db
      .prepare(`
        SELECT et.* FROM event_tags et
        JOIN events e ON e.id = et.event_id
        WHERE e.day_id = ? AND e.is_deleted = 0
        ORDER BY et.event_id ASC, et.is_primary DESC, et.tag_id ASC
      `)
      .all(dayId) as unknown as EventTagRow[];
    return rows.map(rowToEventTag);
  }

  async listAllEventTags(): Promise<EventTag[]> {
    const rows = this.db
      .prepare('SELECT * FROM event_tags ORDER BY event_id ASC, is_primary DESC, tag_id ASC')
      .all() as unknown as EventTagRow[];
    return rows.map(rowToEventTag);
  }

  async listEventTagsModifiedSince(
    cursor: string = '',
    limit: number = 100
  ): Promise<CursorResult<TimestampedEventTag>> {
    const query = cursor
      ? `SELECT et.event_id, et.tag_id, et.is_primary, e.updated_at
         FROM event_tags et JOIN events e ON e.id = et.event_id
         WHERE e.updated_at > ?
         ORDER BY e.updated_at ASC, et.event_id ASC, et.tag_id ASC LIMIT ?`
      : `SELECT et.event_id, et.tag_id, et.is_primary, e.updated_at
         FROM event_tags et JOIN events e ON e.id = et.event_id
         ORDER BY e.updated_at ASC, et.event_id ASC, et.tag_id ASC LIMIT ?`;

    const params = cursor ? [cursor, limit + 1] : [limit + 1];
    const rows = this.db.prepare(query).all(...params) as unknown as EventTagRow[];

    const hasMore = rows.length > limit;
    const recordsToReturn = hasMore ? rows.slice(0, limit) : rows;
    const records = recordsToReturn.map((row) => ({
      link: rowToEventTag(row),
      updatedAt: row.updated_at ?? '',
    }));
    const nextCursor = records.length > 0 ? records[records.length - 1].updatedAt : cursor;

    return { records, nextCursor, hasMore };
  }
}

import { DatabaseSync } from './db.js';
import {
  EventParticipant,
  ParticipantInitiation,
  ParticipantMedium,
  Person,
  UUID,
} from '@life-logger/domain';
import {
  CursorResult,
  IPersonRepository,
  TimestampedEventParticipant,
} from '../interfaces.js';

interface PersonRow {
  id: string;
  display_name: string;
  aliases_json: string;
  notes: string | null;
  created_at: string;
  updated_at: string;
  is_deleted: number;
}

interface ParticipantRow {
  event_id: string;
  person_id: string;
  role: string;
  medium: string;
  initiated_by: string;
  updated_at?: string;
}

function rowToPerson(row: PersonRow): Person {
  let aliases: string[] = [];
  try {
    const parsed = JSON.parse(row.aliases_json);
    if (Array.isArray(parsed)) aliases = parsed.filter((alias) => typeof alias === 'string');
  } catch {
    aliases = [];
  }

  return {
    id: row.id,
    displayName: row.display_name,
    aliases,
    notes: row.notes ?? undefined,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    isDeleted: row.is_deleted === 1,
  };
}

function rowToParticipant(row: ParticipantRow): EventParticipant {
  return {
    eventId: row.event_id,
    personId: row.person_id,
    role: row.role,
    medium: row.medium as ParticipantMedium,
    initiatedBy: row.initiated_by as ParticipantInitiation,
  };
}

function normalizeName(value: string): string {
  return value.trim().replace(/^@+/, '').replace(/\s+/g, ' ').toLowerCase();
}

export class SqlitePersonRepository implements IPersonRepository {
  constructor(private readonly db: DatabaseSync) {}

  async save(person: Person): Promise<void> {
    this.db
      .prepare(`
        INSERT INTO people (
          id, display_name, aliases_json, notes, created_at, updated_at, is_deleted
        ) VALUES (?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
          display_name = excluded.display_name,
          aliases_json = excluded.aliases_json,
          notes = excluded.notes,
          updated_at = excluded.updated_at,
          is_deleted = excluded.is_deleted
        WHERE excluded.updated_at >= people.updated_at
      `)
      .run(
        person.id,
        person.displayName,
        JSON.stringify(person.aliases),
        person.notes ?? null,
        person.createdAt,
        person.updatedAt,
        person.isDeleted ? 1 : 0
      );
  }

  async saveBatch(people: Person[]): Promise<void> {
    if (people.length === 0) return;

    this.db.exec('BEGIN TRANSACTION');
    try {
      for (const person of people) {
        await this.save(person);
      }
      this.db.exec('COMMIT');
    } catch (err) {
      this.db.exec('ROLLBACK');
      throw err;
    }
  }

  async findById(id: UUID): Promise<Person | null> {
    const row = this.db.prepare('SELECT * FROM people WHERE id = ?').get(id) as unknown as
      | PersonRow
      | undefined;
    return row ? rowToPerson(row) : null;
  }

  async findByNameOrAlias(name: string): Promise<Person | null> {
    const needle = normalizeName(name);
    if (!needle) return null;

    for (const person of await this.listAll()) {
      if (normalizeName(person.displayName) === needle) return person;
      if (person.aliases.some((alias) => normalizeName(alias) === needle)) return person;
    }

    return null;
  }

  async listAll(includeDeleted = false): Promise<Person[]> {
    const query = includeDeleted
      ? 'SELECT * FROM people ORDER BY display_name ASC'
      : 'SELECT * FROM people WHERE is_deleted = 0 ORDER BY display_name ASC';
    const rows = this.db.prepare(query).all() as unknown as PersonRow[];
    return rows.map(rowToPerson);
  }

  async linkParticipant(participant: EventParticipant): Promise<void> {
    this.db
      .prepare(`
        INSERT INTO event_participants (event_id, person_id, role, medium, initiated_by)
        VALUES (?, ?, ?, ?, ?)
        ON CONFLICT(event_id, person_id) DO UPDATE SET
          role = excluded.role,
          medium = excluded.medium,
          initiated_by = excluded.initiated_by
      `)
      .run(
        participant.eventId,
        participant.personId,
        participant.role,
        participant.medium,
        participant.initiatedBy
      );
  }

  async listParticipants(eventId: UUID): Promise<EventParticipant[]> {
    const rows = this.db
      .prepare('SELECT * FROM event_participants WHERE event_id = ? ORDER BY person_id ASC')
      .all(eventId) as unknown as ParticipantRow[];
    return rows.map(rowToParticipant);
  }

  async listParticipantsForDay(dayId: UUID): Promise<EventParticipant[]> {
    const rows = this.db
      .prepare(`
        SELECT ep.* FROM event_participants ep
        JOIN events e ON e.id = ep.event_id
        WHERE e.day_id = ? AND e.is_deleted = 0
        ORDER BY ep.event_id ASC, ep.person_id ASC
      `)
      .all(dayId) as unknown as ParticipantRow[];
    return rows.map(rowToParticipant);
  }

  async listAllParticipants(): Promise<EventParticipant[]> {
    const rows = this.db
      .prepare('SELECT * FROM event_participants ORDER BY event_id ASC, person_id ASC')
      .all() as unknown as ParticipantRow[];
    return rows.map(rowToParticipant);
  }

  async listParticipantsModifiedSince(
    cursor: string = '',
    limit: number = 100
  ): Promise<CursorResult<TimestampedEventParticipant>> {
    const query = cursor
      ? `SELECT ep.event_id, ep.person_id, ep.role, ep.medium, ep.initiated_by, e.updated_at
         FROM event_participants ep JOIN events e ON e.id = ep.event_id
         WHERE e.updated_at > ?
         ORDER BY e.updated_at ASC, ep.event_id ASC, ep.person_id ASC LIMIT ?`
      : `SELECT ep.event_id, ep.person_id, ep.role, ep.medium, ep.initiated_by, e.updated_at
         FROM event_participants ep JOIN events e ON e.id = ep.event_id
         ORDER BY e.updated_at ASC, ep.event_id ASC, ep.person_id ASC LIMIT ?`;

    const params = cursor ? [cursor, limit + 1] : [limit + 1];
    const rows = this.db.prepare(query).all(...params) as unknown as ParticipantRow[];

    const hasMore = rows.length > limit;
    const recordsToReturn = hasMore ? rows.slice(0, limit) : rows;
    const records = recordsToReturn.map((row) => ({
      participant: rowToParticipant(row),
      updatedAt: row.updated_at ?? '',
    }));
    const nextCursor = records.length > 0 ? records[records.length - 1].updatedAt : cursor;

    return { records, nextCursor, hasMore };
  }
}

