60:     let person = findPersonByNameOrAlias(known, normalized);
61:     if (!person) {
62:       person = {
63:         id: makeId(normalized),
64:         displayName,
65:         aliases: [],
66:         createdAt: now.toISOString(),
67:         updatedAt: now.toISOString(),
68:         isDeleted: false,
69:       };
70:       known.push(person);
71:       created.push(person);
72:     }
73: 
74:     if (seenPersonIds.has(person.id)) continue;
75:     seenPersonIds.add(person.id);
