import {
  Capture,
  Day,
  Event,
  EventParticipant,
  EventTag,
  JournalEntry,
  Marker,
  Person,
  Tag,
  TimelineGap,
} from '@life-logger/domain';

const API_BASE = '';

export interface DayTimeline {
  day: Day;
  markers: Marker[];
  events: Event[];
  tags: Tag[];
  eventTags: EventTag[];
  people: Person[];
  participants: EventParticipant[];
  journalEntries: JournalEntry[];
  gaps: TimelineGap[];
  coverage: number;
}

export interface CreateEventInput {
  event: Partial<Event> & Pick<Event, 'title' | 'startAt'>;
  tagPaths?: string[];
  peopleNames?: string[];
  capture?: Capture;
}

export interface CreateEventResult {
  event: Event;
  tags: Tag[];
  eventTags: EventTag[];
  people: Person[];
  participants: EventParticipant[];
  capture: Capture | null;
}

export interface DayPatchInput {
  wakeAt?: string;
  sleepAt?: string;
  reviewStatus?: Day['reviewStatus'];
  timezone?: string;
}

export interface ReviewInput {
  sleepAt?: string;
  journalId?: string;
  journalBody?: string;
}

export interface ReviewResult {
  day: Day;
  fidelity: Day['fidelity'];
  coverage: number;
  gaps: TimelineGap[];
  journalEntries: JournalEntry[];
}

async function readJson<T>(res: Response, fallbackMessage: string): Promise<T> {
  if (!res.ok) {
    const detail = await res.text();
    throw new Error(`${fallbackMessage} (HTTP ${res.status})${detail ? `: ${detail}` : ''}`);
  }
  return res.json() as Promise<T>;
}

export async function fetchActiveDay(timezone?: string): Promise<Day> {
  const query = timezone ? `?timezone=${encodeURIComponent(timezone)}` : '';
  const res = await fetch(`${API_BASE}/api/v1/days/active${query}`);
  return readJson<Day>(res, 'Failed to fetch active day');
}

export async function fetchDayTimeline(dayId: string): Promise<DayTimeline> {
  const res = await fetch(`${API_BASE}/api/v1/days/${encodeURIComponent(dayId)}/timeline`);
  return readJson<DayTimeline>(res, 'Failed to fetch day timeline');
}

export async function fetchMarkers(dayId?: string): Promise<Marker[]> {
  const url = dayId
    ? `${API_BASE}/api/v1/markers?dayId=${encodeURIComponent(dayId)}`
    : `${API_BASE}/api/v1/markers`;
  const res = await fetch(url);
  return readJson<Marker[]>(res, 'Failed to fetch markers');
}

export async function updateDay(dayId: string, patch: DayPatchInput): Promise<Day> {
  const res = await fetch(`${API_BASE}/api/v1/days/${encodeURIComponent(dayId)}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(patch),
  });
  return readJson<Day>(res, 'Failed to update day');
}

export async function createEvent(input: CreateEventInput): Promise<CreateEventResult> {
  const res = await fetch(`${API_BASE}/api/v1/events`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  });
  return readJson<CreateEventResult>(res, 'Failed to create event');
}

export async function saveJournal(dayId: string, body: string): Promise<JournalEntry> {
  const res = await fetch(`${API_BASE}/api/v1/days/${encodeURIComponent(dayId)}/journal`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ body }),
  });
  return readJson<JournalEntry>(res, 'Failed to save journal');
}

export async function reviewDay(dayId: string, input: ReviewInput): Promise<ReviewResult> {
  const res = await fetch(`${API_BASE}/api/v1/days/${encodeURIComponent(dayId)}/review`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  });
  return readJson<ReviewResult>(res, 'Failed to complete day review');
}

export async function checkServerHealth(): Promise<boolean> {
  try {
    const res = await fetch(`${API_BASE}/health`);
    return res.ok;
  } catch {
    return false;
  }
}

import React, { useState } from 'react';
import { Day, TimelineGap } from '@life-logger/domain';
import { ReviewInput, ReviewResult } from '../api.js';

interface GapTemplate {
  label: string;
  title: string;
  tagPaths: string[];
}

const GAP_TEMPLATES: GapTemplate[] = [
  { label: 'Deep Work', title: 'Deep work', tagPaths: ['work/coding'] },
  { label: 'Meal', title: 'Meal', tagPaths: ['food'] },
  { label: 'Rest', title: 'Rest', tagPaths: ['rest'] },
];

interface ReviewModalProps {
  day: Day;
  gaps: TimelineGap[];
  initialJournal: string;
  onClose: () => void;
  onFillGap: (gap: TimelineGap, template: GapTemplate) => Promise<TimelineGap[]>;
  onComplete: (input: ReviewInput) => Promise<ReviewResult>;
}

function formatClock(iso: string): string {
  return new Date(iso).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

function toTimeInput(iso?: string): string {
  if (!iso) return '';
  const date = new Date(iso);
  return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
}

function sleepTimeToIso(day: Day, value: string): string | undefined {
  const match = /^(\d{1,2}):(\d{2})$/.exec(value.trim());
  if (!match) return undefined;

  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours > 23 || minutes > 59) return undefined;

  const candidate = new Date(`${day.localDate}T${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:00`);

  if (day.wakeAt && candidate.getTime() < new Date(day.wakeAt).getTime()) {
    candidate.setDate(candidate.getDate() + 1);
  }

  return candidate.toISOString();
}

export const ReviewModal: React.FC<ReviewModalProps> = ({
  day,
  gaps,
  initialJournal,
  onClose,
  onFillGap,
  onComplete,
}) => {
  const [currentGaps, setCurrentGaps] = useState<TimelineGap[]>(gaps);
  const [journal, setJournal] = useState(initialJournal);
  const [sleepTime, setSleepTime] = useState(toTimeInput(day.sleepAt));
  const [busyGap, setBusyGap] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<ReviewResult | null>(null);

  const handleFill = async (gap: TimelineGap, template: GapTemplate) => {
    setBusyGap(gap.startAt);
    setError(null);
    try {
      const nextGaps = await onFillGap(gap, template);
      setCurrentGaps(nextGaps);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fill gap');
    } finally {
      setBusyGap(null);
    }
  };

  const handleComplete = async () => {
    setSubmitting(true);
    setError(null);
    try {
      const review = await onComplete({
        sleepAt: sleepTimeToIso(day, sleepTime),
        journalBody: journal.trim() || undefined,
      });
      setResult(review);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to complete review');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div style={styles.backdrop} role="dialog" aria-modal="true">
      <div style={styles.panel}>
        {result ? (
          <div style={styles.completion}>
            <div style={styles.confetti}>🎉</div>
            <h2 style={styles.title}>Day complete</h2>
            <div style={styles.fidelity}>{result.fidelity}</div>
            <p style={styles.completionMeta}>
              {Math.round(result.coverage * 100)}% of waking hours covered ·{' '}
              {result.gaps.length} gaps left
            </p>
            <button type="button" style={styles.primary} onClick={onClose}>
              DONE
            </button>
          </div>
        ) : (
          <>
            <div style={styles.headerRow}>
              <div>
                <h2 style={styles.title}>End-of-Day Review</h2>
                <p style={styles.subtitle}>
                  Fill the gaps, capture a reflection, then record sleep.
                </p>
              </div>
              <button type="button" style={styles.close} onClick={onClose} aria-label="Close review">
                ×
              </button>
            </div>

            {error && <div style={styles.error}>{error}</div>}

            <h3 style={styles.label}>UNLOGGED GAPS &gt; 15 MIN</h3>
            {currentGaps.length === 0 ? (
              <p style={styles.empty}>No gaps. Beautifully logged day!</p>
            ) : (
              currentGaps.map((gap) => (
                <div key={`review-gap-${gap.startAt}`} style={styles.gapRow}>
                  <div style={styles.gapInfo}>
                    <div style={styles.gapTime}>
                      {formatClock(gap.startAt)} – {formatClock(gap.endAt)}
                    </div>
                    <div style={styles.gapMeta}>{Math.round(gap.durationMinutes)} min unlogged</div>
                  </div>
                  <div style={styles.templates}>
                    {GAP_TEMPLATES.map((template) => (
                      <button
                        key={template.label}
                        type="button"
                        style={styles.templateButton}
                        disabled={busyGap === gap.startAt}
                        onClick={() => handleFill(gap, template)}
                      >
                        {template.label}
                      </button>
                    ))}
                  </div>
                </div>
              ))
            )}

            <label style={styles.inputLabel} htmlFor="review-journal">
              Reflections on today?
            </label>
            <textarea
              id="review-journal"
              style={styles.textarea}
              placeholder="What mattered? What did you learn?"
              value={journal}
              onChange={(event) => setJournal(event.target.value)}
            />

            <label style={styles.inputLabel} htmlFor="review-sleep">
              Sleep time
            </label>
            <input
              id="review-sleep"
              type="time"
              style={styles.input}
              value={sleepTime}
              onChange={(event) => setSleepTime(event.target.value)}
            />

            <button
              type="button"
              style={styles.primary}
              disabled={submitting}
              onClick={handleComplete}
            >
              {submitting ? 'COMPLETING…' : 'COMPLETE DAY REVIEW'}
            </button>
          </>
        )}
      </div>
    </div>
  );
};

