245:       id: `event-phone-${Date.now()}`,
246:       dayId: day.id,
247:       source: 'live',
248:       now,
249:     });
250: 
251:     const result = await persistEvent({
252:       title: built.title,
253:       startAt: built.startAt,
254:       endAt: built.endAt,
255:       tagPaths: parsed.tagPaths,
256:       peopleNames: parsed.peopleNames,
257:       capture: {
258:         rawText: parsed.rawText,
259:         capturedAt: parsed.startAt,
260:         parsedBy: parsed.parsedBy,
261:       },
262:     });
263: 
264:     if (result) {
265:       setLastSaveLatency(result.saveDurationMs);
266:       setQuickText('');
267:     }
268:   };
269: 
270:   const handleMarkNow = async () => {
271:     if (!day) return;
272:     Vibration.vibrate(50);
273:     const now = new Date();
274:     const newMarker: Marker = {
275:       id: `m-phone-${Date.now()}`,
276:       dayId: day.id,
277:       markedAt: now.toISOString(),
278:       timezoneOffsetMinutes: -new Date().getTimezoneOffset(),
279:       note: noteText.trim() || undefined,
280:       precision: 'exact',
281:       source: 'live',
282:       createdAt: now.toISOString(),
283:       updatedAt: now.toISOString(),
284:       isDeleted: false,
285:     };
286: 
287:     const { saveDurationMs } = await storage.saveMarkerAndEnqueueOutbox(newMarker);
288:     setLastSaveLatency(saveDurationMs);
289:     setMarkers((prev) => [newMarker, ...prev]);
290:     setNoteText('');
291:     await refreshOutbox();
292:   };
293: 
294:   const handleWake = async () => {
295:     if (!day || day.wakeAt) return;
296:     const updated = wakeDay(day, new Date().toISOString());
297:     await storage.saveDayAndEnqueueOutbox(updated);
298:     setDay(updated);
299:     await refreshOutbox();
300:   };
301: 
302:   const handleSyncNow = async () => {
303:     setSyncStatus('Syncing...');
304:     const res = await syncClient.syncNow();
305:     if (res.error) {
306:       setSyncStatus(`Sync error: ${res.error}`);
307:     } else {
308:       setSyncStatus(`Synced ${res.syncedCount} records`);
309:     }
310:     await refreshOutbox();
311:   };
312: 
313:   const openReview = () => {
314:     if (!day) return;
315:     const now = new Date();
316:     setReviewGaps(findTimelineGaps(day, events, MIN_GAP_MINUTES, now));
317:     setJournalDraft(journalEntries[0]?.body ?? '');
318:     setSleepDraft(toTimeInput(day.sleepAt));
319:     setReviewResult(null);
320:     setReviewOpen(true);
321:   };
322: 
323:   const handleFillGap = async (gap: TimelineGap) => {
324:     if (!day) return;
325:     const result = await persistEvent({
326:       title: 'Deep work',
327:       startAt: gap.startAt,
328:       endAt: gap.endAt,
329:       tagPaths: ['work/coding'],
330:     });
331:     if (result) {
332:       setReviewGaps(findTimelineGaps(day, result.events, MIN_GAP_MINUTES, new Date()));
333:     }
334:   };
335: 
336:   const handleCompleteReview = async () => {
337:     if (!day) return;
338: 
339:     const now = new Date();
340:     let nextJournalEntries = journalEntries;
341: 
342:     if (journalDraft.trim().length > 0) {
343:       const entry: JournalEntry = {
344:         id: `journal-${day.id}`,
345:         dayId: day.id,
346:         body: journalDraft.trim(),
347:         writtenAt: now.toISOString(),
348:         source: 'live',
349:         createdAt: now.toISOString(),
350:         updatedAt: now.toISOString(),
351:         isDeleted: false,
352:       };
353:       await storage.saveJournalAndEnqueueOutbox(entry);
354:       nextJournalEntries = [entry];
355:       setJournalEntries(nextJournalEntries);
356:     }
357: 
358:     const sleepAt = parseSleepTime(sleepDraft, day, now);
359:     const closing = completeDayReview(day, events, nextJournalEntries, {
360:       now,
361:       sleepAt,
362:     });
363: 
364:     await storage.saveDayAndEnqueueOutbox(closing);
365: 
366:     const coverage = calculateDayCoverage(closing, events, now);
367:     const remainingGaps = findTimelineGaps(closing, events, MIN_GAP_MINUTES, now);
368: 
369:     setDay(closing);
370:     setReviewGaps(remainingGaps);
371:     setReviewResult({
372:       fidelity: closing.fidelity,
373:       coverage,
374:       gapsRemaining: remainingGaps.length,
375:     });
376:     await refreshOutbox();
377:   };
378: 
379:   const activeDay = day;
380:   const lanes = computeTimelineLanes(events);
381:   const nowMs = Date.now();
382:   const windowStartMs = activeDay?.wakeAt ? new Date(activeDay.wakeAt).getTime() : nowMs;
383:   const windowEndMs = activeDay?.sleepAt ? new Date(activeDay.sleepAt).getTime() : nowMs;
384:   const spanMs = Math.max(windowEndMs - windowStartMs, 60 * 60 * 1000);
385:   const laneCount =
386:     lanes.reduce((max, item) => Math.max(max, item.totalLanes), 1) || 1;
387:   const timelineGaps = activeDay
388:     ? findTimelineGaps(activeDay, events, MIN_GAP_MINUTES, new Date(nowMs))
389:     : [];
390:   const coverage = activeDay ? calculateDayCoverage(activeDay, events, new Date(nowMs)) : 0;
391: 
392:   const renderTimelineBar = () => {
393:     if (!activeDay?.wakeAt) {
394:       return (
395:         <Text style={styles.emptyText}>
396:           Wake up to start the day timeline. Quick entries are still saved offline.
397:         </Text>
398:       );
399:     }
400: 
401:     return (
402:       <View style={[styles.miniTimeline, { height: 12 * laneCount + 8 }]}>
403:         <View style={styles.timelineTrack} />
404:         {timelineGaps.map((gap) => {
405:           const start = Math.max(
406:             0,
407:             ((new Date(gap.startAt).getTime() - windowStartMs) / spanMs) * 100
408:           );
409:           const width = Math.max(
410:             0.5,
411:             ((new Date(gap.endAt).getTime() - new Date(gap.startAt).getTime()) / spanMs) * 100
412:           );
413:           return (
414:             <View
415:               key={`gap-${gap.startAt}`}
416:               style={[
417:                 styles.gapBlock,
418:                 { left: `${start}%`, width: `${Math.min(width, 100 - start)}%` },
419:               ]}
420:             />
421:           );
422:         })}
423:         {lanes.map(({ event, laneIndex }) => {
424:           const startMs = new Date(event.startAt).getTime();
425:           const endMs = event.endAt ? new Date(event.endAt).getTime() : startMs;
426:           const left = Math.max(0, ((startMs - windowStartMs) / spanMs) * 100);
427:           const width = Math.max(0.7, ((endMs - startMs) / spanMs) * 100);
428:           return (
429:             <View
430:               key={event.id}
431:               style={[
432:                 styles.eventBlock,
433:                 {
434:                   left: `${Math.min(left, 99)}%`,
435:                   width: `${Math.min(width, 100 - left)}%`,
436:                   top: 4 + laneIndex * 12,
437:                 },
438:               ]}
439:             />
440:           );
441:         })}
442:       </View>
443:     );
444:   };
445: 
446:   return (
447:     <SafeAreaView style={styles.container}>
448:       <StatusBar barStyle="light-content" backgroundColor="#0f172a" />
449: 
450:       <ScrollView
451:         contentContainerStyle={styles.scrollContent}
452:         keyboardShouldPersistTaps="handled"
453:       >
454:         <View style={styles.header}>
455:           <View>
456:             <Text style={styles.title}>Life Logger</Text>
457:             <Text style={styles.subtitle}>
458:               {activeDay ? activeDay.localDate : 'Loading day...'} · Daily Loop
459:             </Text>
460:           </View>
461:           {activeDay && (
462:             <View style={styles.fidelityPill}>
463:               <Text style={styles.fidelityText}>{activeDay.fidelity}</Text>
464:             </View>
465:           )}
466:         </View>
467: 
468:         <View style={styles.dayCard}>
469:           <View style={styles.dayRow}>
470:             <View style={{ flex: 1 }}>
471:               <Text style={styles.dayLabel}>
472:                 {activeDay?.wakeAt ? `Awake since ${formatClock(activeDay.wakeAt)}` : 'Not awake yet'}
473:               </Text>
474:               <Text style={styles.dayMeta}>
475:                 {Math.round(coverage * 100)}% timeline coverage ·{' '}
476:                 {timelineGaps.length} {timelineGaps.length === 1 ? 'gap' : 'gaps'} ·{' '}
477:                 {activeDay?.reviewStatus ?? 'unreviewed'}
478:               </Text>
479:             </View>
480:             {!activeDay?.wakeAt && (
481:               <TouchableOpacity style={styles.wakeButton} onPress={handleWake}>
482:                 <Text style={styles.wakeButtonText}>WAKE UP</Text>
483:               </TouchableOpacity>
484:             )}
485:           </View>
486: 
487:           {renderTimelineBar()}
488: 
489:           <TouchableOpacity style={styles.reviewButton} onPress={openReview}>
490:             <Text style={styles.reviewButtonText}>
491:               {activeDay?.reviewStatus === 'completed' ? 'Reopen Day Review' : 'Start Day Review'}
492:             </Text>
493:           </TouchableOpacity>
494:         </View>
495: 
496:         <View style={styles.card}>
497:           <Text style={styles.cardLabel}>QUICK ENTRY</Text>
