526:                 >
527:                   <Text style={styles.suggestionText}>@{person.displayName}</Text>
528:                 </TouchableOpacity>
529:               ))}
530:             </View>
531:           )}
532:           <TouchableOpacity
533:             style={[styles.quickButton, !quickText.trim() && styles.disabledButton]}
534:             onPress={handleQuickEntry}
535:             disabled={!quickText.trim()}
