682:                         >
683:                           <Text style={styles.gapFillText}>Deep Work #work/coding</Text>
684:                         </TouchableOpacity>
685:                       </View>
686:                     ))
687:                   )}
688: 
689:                   <Text style={styles.inputLabel}>Reflections on today?</Text>
690:                   <TextInput
691:                     style={[styles.input, styles.journalInput]}
692:                     placeholder="What mattered? What did you learn?"
693:                     placeholderTextColor="#94a3b8"
694:                     value={journalDraft}
695:                     onChangeText={setJournalDraft}
696:                     multiline
697:                   />
698: 
699:                   <Text style={styles.inputLabel}>Sleep time (HH:MM)</Text>
700:                   <TextInput
