716:                     style={styles.cancelButton}
717:                     onPress={() => setReviewOpen(false)}
718:                   >
719:                     <Text style={styles.cancelButtonText}>Cancel</Text>
720:                   </TouchableOpacity>
721:                 </>
722:               )}
723:             </ScrollView>
724:           </View>
725:         </View>
726:       </Modal>
727:     </SafeAreaView>
728:   );
729: }
