import { describe, it, expect } from 'vitest';
import {
  acceptSuggestion,
  buildEventFromSuggestion,
  buildSuggestion,
  editSuggestion,
  isSuggestionPending,
  rejectSuggestion,
} from '../src/suggestions.js';
import { Suggestion } from '../src/types.js';

const NOW = new Date('2026-10-14T09:00:00.000Z');

function draft(overrides: Partial<Parameters<typeof buildSuggestion>[0]> = {}) {
  return {
    source: 'calendar' as const,
    confidence: 0.9,
    externalId: 'uid-1',
    proposed: {
      title: 'Planning',
      startAt: '2026-10-14T10:00:00.000Z',
      endAt: '2026-10-14T11:00:00.000Z',
      startPrecision: 'approx' as const,
      endPrecision: 'approx' as const,
    },
    ...overrides,
  };
}

function suggestion(): Suggestion {
  return buildSuggestion(draft(), { id: 'suggestion-1', now: NOW });
}

describe('buildSuggestion', () => {
  it('creates a pending suggestion with clamped confidence', () => {
    const result = buildSuggestion(draft({ confidence: 1.5 }), { id: 's-1', now: NOW });
    expect(result.status).toBe('pending');
    expect(result.confidence).toBe(1);
    expect(result.createdAt).toBe(NOW.toISOString());
    expect(isSuggestionPending(result)).toBe(true);
  });

  it('rejects an empty title', () => {
    expect(() =>
      buildSuggestion(draft({ proposed: { ...draft().proposed, title: '   ' } }), {
        id: 's-1',
        now: NOW,
      })
    ).toThrow(/title/i);
  });

  it('rejects an end time before the start', () => {
    expect(() =>
      buildSuggestion(
        draft({
          proposed: {
            ...draft().proposed,
            endAt: '2026-10-14T09:00:00.000Z',
          },
        }),
        { id: 's-1', now: NOW }
      )
    ).toThrow(/after start/i);
  });
});

describe('editSuggestion', () => {
  it('updates proposed fields while staying pending', () => {
    const edited = editSuggestion(
      suggestion(),
      {
        title: 'Planning revised',
        startAt: '2026-10-14T10:30:00.000Z',
        endAt: '2026-10-14T12:00:00.000Z',
        tagPaths: ['work/planning'],
      },
      NOW
    );

    expect(edited.status).toBe('pending');
    expect(edited.proposed.title).toBe('Planning revised');
    expect(edited.proposed.tagPaths).toEqual(['work/planning']);
    expect(edited.updatedAt).toBe(NOW.toISOString());
  });

  it('clears an end time with null', () => {
    const edited = editSuggestion(suggestion(), { endAt: null }, NOW);
    expect(edited.proposed.endAt).toBeUndefined();
  });

  it('refuses to edit a reviewed suggestion', () => {
    const rejected = rejectSuggestion(suggestion(), NOW);
    expect(() => editSuggestion(rejected, { title: 'nope' }, NOW)).toThrow(/rejected/i);
  });
});

describe('acceptSuggestion', () => {
  it('marks the suggestion accepted and returns the final proposal', () => {
    const { suggestion: accepted, proposed } = acceptSuggestion(
      suggestion(),
      { title: 'Planning (confirmed)' },
      { eventId: 'event-1', dayId: 'day-2026-10-14', now: NOW }
    );

    expect(accepted.status).toBe('accepted');
    expect(accepted.acceptedEventId).toBe('event-1');
    expect(accepted.reviewedAt).toBe(NOW.toISOString());
    expect(proposed.title).toBe('Planning (confirmed)');

    const event = buildEventFromSuggestion(proposed, {
      eventId: 'event-1',
      dayId: 'day-2026-10-14',
      now: NOW,
    });
    expect(event.source).toBe('imported');
    expect(event.title).toBe('Planning (confirmed)');
    expect(event.startPrecision).toBe('approx');
  });

  it('cannot accept twice', () => {
    const { suggestion: accepted } = acceptSuggestion(suggestion(), undefined, {
      eventId: 'event-1',
      dayId: 'day-2026-10-14',
      now: NOW,
    });

    expect(() =>
      acceptSuggestion(accepted, undefined, {
        eventId: 'event-2',
        dayId: 'day-2026-10-14',
        now: NOW,
      })
    ).toThrow(/accepted/i);
  });

  it('rejects an invalid override time', () => {
    expect(() =>
      acceptSuggestion(suggestion(), { startAt: 'not-a-date' }, {
        eventId: 'event-1',
        dayId: 'day-2026-10-14',
        now: NOW,
      })
    ).toThrow(/Invalid suggestion start time/i);
  });
});

describe('rejectSuggestion', () => {
  it('records the decision without creating an event', () => {
    const rejected = rejectSuggestion(suggestion(), NOW);
    expect(rejected.status).toBe('rejected');
    expect(rejected.acceptedEventId).toBeUndefined();
    expect(rejected.reviewedAt).toBe(NOW.toISOString());
  });
});

import { describe, it, expect } from 'vitest';
import {
  calendarEventsToSuggestions,
  calendarSuggestionId,
  parseIcsCalendar,
} from '../src/calendar.js';
import { createDefaultExtensionRegistry, CALENDAR_EXTENSION, ExtensionRegistry } from '../src/extensions.js';

function ics(body: string): string {
  return ['BEGIN:VCALENDAR', 'VERSION:2.0', body, 'END:VCALENDAR'].join('\r\n');
}

describe('parseIcsCalendar', () => {
  it('parses a timezone-aware event with attendees and recurrence', () => {
    const result = parseIcsCalendar(
      ics(
        [
          'BEGIN:VEVENT',
          'UID:event-1@example.com',
          'SUMMARY:Team planning',
          'DTSTART;TZID=America/New_York:20261014T100000',
          'DTEND;TZID=America/New_York:20261014T110000',
          'LOCATION:Room 4',
          'DESCRIPTION:Plan the next cycle',
          'ORGANIZER;CN=Alex:mailto:alex@example.com',
          'ATTENDEE;CN=Rahul:mailto:rahul@example.com',
          'RRULE:FREQ=WEEKLY',
          'END:VEVENT',
        ].join('\r\n')
      )
    );

    expect(result.skipped).toEqual([]);
    expect(result.events).toHaveLength(1);
    const event = result.events[0];
    expect(event.title).toBe('Team planning');
    expect(event.startAt).toBe('2026-10-14T14:00:00.000Z');
    expect(event.endAt).toBe('2026-10-14T15:00:00.000Z');
    expect(event.timezone).toBe('America/New_York');
    expect(event.location).toBe('Room 4');
    expect(event.organizer).toBe('Alex');
    expect(event.attendees).toEqual(['Rahul']);
    expect(event.recurrenceRule).toBe('FREQ=WEEKLY');
  });

  it('parses all-day events into a full-day interval', () => {
    const result = parseIcsCalendar(
      ics(
        [
          'BEGIN:VEVENT',
          'UID:holiday',
          'SUMMARY:Public holiday',
          'DTSTART;VALUE=DATE:20261015',
          'END:VEVENT',
        ].join('\n')
      )
    );

    expect(result.events[0].allDay).toBe(true);
    expect(result.events[0].startAt).toBe('2026-10-15T00:00:00.000Z');
    expect(result.events[0].endAt).toBe('2026-10-15T23:59:59.999Z');
  });

  it('computes the end from DURATION', () => {
    const result = parseIcsCalendar(
      ics(
        [
          'BEGIN:VEVENT',
          'UID:focus',
          'SUMMARY:Focus block',
          'DTSTART:20261014T090000Z',
          'DURATION:PT1H30M',
          'END:VEVENT',
        ].join('\n')
      )
    );

    expect(result.events[0].startAt).toBe('2026-10-14T09:00:00.000Z');
    expect(result.events[0].endAt).toBe('2026-10-14T10:30:00.000Z');
  });

  it('unfolds folded lines and unescapes text', () => {
    const result = parseIcsCalendar(
      ics(
        [
          'BEGIN:VEVENT',
          'UID:folded',
          'SUMMARY:Lunch\\, then walk\\nHome',
          'DTSTART:20261014T120000Z',
          'END:VEVENT',
        ].join('\n')
      )
    );

    expect(result.events[0].title).toBe('Lunch, then walk\nHome');
  });

  it('skips malformed events without throwing', () => {
    const result = parseIcsCalendar(
      ics(
        [
          'BEGIN:VEVENT',
          'UID:broken',
          'SUMMARY:No start',
          'END:VEVENT',
          'BEGIN:VEVENT',
          'UID:good',
          'SUMMARY:Good event',
          'DTSTART:20261014T120000Z',
          'END:VEVENT',
        ].join('\n')
      )
    );

    expect(result.events).toHaveLength(1);
    expect(result.events[0].title).toBe('Good event');
    expect(result.skipped).toHaveLength(1);
  });

  it('returns an empty result for blank input', () => {
    expect(parseIcsCalendar('')).toEqual({ events: [], skipped: [] });
    expect(parseIcsCalendar('   ')).toEqual({ events: [], skipped: [] });
  });
});

describe('calendarEventsToSuggestions', () => {
  it('produces deterministic pending suggestions with approx precision', () => {
    const parsed = parseIcsCalendar(
      ics(
        [
          'BEGIN:VEVENT',
          'UID:planning',
          'SUMMARY:Planning',
          'DTSTART:20261014T120000Z',
          'DTEND:20261014T130000Z',
          'END:VEVENT',
        ].join('\n')
      )
    );

    const suggestions = calendarEventsToSuggestions(parsed.events, {
      now: new Date('2026-10-14T09:00:00.000Z'),
    });

    expect(suggestions).toHaveLength(1);
    expect(suggestions[0].id).toBe(calendarSuggestionId('planning'));
    expect(suggestions[0].source).toBe('calendar');
    expect(suggestions[0].status).toBe('pending');
    expect(suggestions[0].proposed.startPrecision).toBe('approx');
    expect(suggestions[0].externalId).toBe('planning');
  });

  it('deduplicates repeated external ids within one import', () => {
    const parsed = parseIcsCalendar(
      ics(
        [
          'BEGIN:VEVENT',
          'UID:same',
          'SUMMARY:First',
          'DTSTART:20261014T120000Z',
          'END:VEVENT',
          'BEGIN:VEVENT',
          'UID:same',
          'SUMMARY:Second',
          'DTSTART:20261015T120000Z',
          'END:VEVENT',
        ].join('\n')
      )
    );

    const suggestions = calendarEventsToSuggestions(parsed.events);
    expect(suggestions).toHaveLength(1);
    expect(suggestions[0].proposed.title).toBe('First');
  });
});

describe('ExtensionRegistry', () => {
  it('registers the calendar extension by default', () => {
    const registry = createDefaultExtensionRegistry();
    expect(registry.get('calendar')).toEqual(CALENDAR_EXTENSION);
    expect(registry.list().map((entry) => entry.id)).toEqual(['calendar']);
  });

  it('rejects duplicate registrations and invalid ids', () => {
    const registry = new ExtensionRegistry();
    registry.register(CALENDAR_EXTENSION);
    expect(() => registry.register(CALENDAR_EXTENSION)).toThrow(/already registered/i);
    expect(() =>
      registry.register({ ...CALENDAR_EXTENSION, id: 'Not Valid' })
    ).toThrow(/Invalid extension id/i);
  });
});

