156:               {Math.round(coverage * 100)}% of waking hours covered · {gaps.length}{' '}
157:               {gaps.length === 1 ? 'gap' : 'gaps'} · {events.length}{' '}
158:               {events.length === 1 ? 'event' : 'events'}
159:             </div>
160:           </div>
161:           {!day?.wakeAt && (
162:             <button style={styles.wakeButton} onClick={handleWake} disabled={waking || !day}>
163:               {waking ? 'Starting…' : 'WAKE UP'}
164:             </button>
165:           )}
166:         </div>
167: 
168:         <div style={styles.coverageTrack}>
169:           <div
170:             style={{
171:               ...styles.coverageFill,
172:               width: `${Math.round(Math.min(1, coverage) * 100)}%`,
173:             }}
174:           />
175:         </div>
176: 
177:         <div style={styles.timelineFrame}>
178:           <div
179:             style={{
180:               ...styles.timelineInner,
181:               height: `${Math.max(86, 10 + laneCount * 38)}px`,
182:             }}
183:           >
184:             {day?.wakeAt && gaps.map((gap) => {
185:               const startMs = new Date(gap.startAt).getTime();
186:               const endMs = new Date(gap.endAt).getTime();
187:               return (
188:                 <div
189:                   key={`gap-${gap.startAt}`}
190:                   title={`Unlogged ${formatClock(gap.startAt)}–${formatClock(gap.endAt)}`}
191:                   style={{
192:                     ...styles.gapBlock,
193:                     left: `${positionStart(startMs)}%`,
194:                     width: `${positionWidth(startMs, endMs)}%`,
195:                   }}
196:                 />
197:               );
198:             })}
199: 
200:             {lanes.map(({ event, laneIndex }) => {
201:               const startMs = new Date(event.startAt).getTime();
202:               const endMs = event.endAt ? new Date(event.endAt).getTime() : startMs;
203:               const paths = tagsForEvent(event.id);
204:               return (
205:                 <div
206:                   key={event.id}
207:                   title={`${event.title} (${formatClock(event.startAt)}–${formatClock(event.endAt)})`}
208:                   style={{
209:                     ...styles.eventBlock,
210:                     left: `${positionStart(startMs)}%`,
211:                     width: `${positionWidth(startMs, endMs)}%`,
212:                     top: 10 + laneIndex * 38,
213:                   }}
214:                 >
215:                   <span style={styles.eventBlockTitle}>{event.title}</span>
216:                   <span style={styles.eventBlockTime}>
217:                     {formatClock(event.startAt)}
218:                     {event.endAt ? `–${formatClock(event.endAt)}` : ''}
219:                   </span>
220:                   {paths.length > 0 && (
221:                     <span style={styles.eventBlockTags}>#{paths.join(' #')}</span>
222:                   )}
223:                 </div>
224:               );
225:             })}
226: 
227:             {!day?.wakeAt && events.length === 0 && (
228:               <div style={styles.timelineEmpty}>
229:                 Set your wake time or log a quick entry to start today's timeline.
230:               </div>
231:             )}
232:           </div>
233:         </div>
234: 
235:         <div style={styles.axis}>
236:           <span>{formatClock(new Date(windowStartMs).toISOString())}</span>
237:           <span>{formatClock(new Date((windowStartMs + windowEndMs) / 2).toISOString())}</span>
238:           <span>{formatClock(new Date(windowEndMs).toISOString())}</span>
239:         </div>
240: 
241:         {gaps.length > 0 && day?.wakeAt && (
242:           <div style={styles.gapList}>
243:             {gaps.slice(0, 3).map((gap) => (
244:               <span key={`gap-chip-${gap.startAt}`} style={styles.gapChip}>
245:                 Gap {formatClock(gap.startAt)}–{formatClock(gap.endAt)} ·{' '}
246:                 {formatDuration(gap.durationMinutes)}
247:               </span>
248:             ))}
249:             {gaps.length > 3 && <span style={styles.gapChip}>+{gaps.length - 3} more</span>}
250:           </div>
251:         )}
252:       </section>
253: 
254:       <section style={styles.card}>
255:         <h2 style={styles.cardTitle}>QUICK ENTRY</h2>
256:         <form onSubmit={handleQuickSubmit} style={styles.quickForm}>
257:           <input
258:             style={styles.quickInput}
259:             placeholder="lunch with @rahul at 1pm #food/lunch"
260:             value={quickText}
261:             onChange={(event) => setQuickText(event.target.value)}
262:           />
263:           <button type="submit" style={styles.quickButton} disabled={!quickText.trim() || savingQuick}>
264:             {savingQuick ? 'Saving…' : 'LOG'}
265:           </button>
266:         </form>
267:         {(tags.length > 0 || people.length > 0) && (
268:           <div style={styles.suggestions}>
269:             {tags.slice(0, 5).map((tag) => (
270:               <button
271:                 key={`suggest-tag-${tag.id}`}
272:                 type="button"
273:                 style={styles.tagSuggestion}
274:                 onClick={() =>
275:                   setQuickText((previous) => `${previous} #${tag.path} `.trimStart())
276:                 }
277:               >
278:                 #{tag.path}
279:               </button>
280:             ))}
281:             {people.slice(0, 4).map((person) => (
282:               <button
283:                 key={`suggest-person-${person.id}`}
284:                 type="button"
285:                 style={styles.personSuggestion}
286:                 onClick={() =>
287:                   setQuickText((previous) => `${previous} @${person.displayName} `.trimStart())
288:                 }
289:               >
290:                 @{person.displayName}
291:               </button>
292:             ))}
293:           </div>
294:         )}
295:         {preview && (
296:           <div style={styles.previewRow}>
297:             <span style={styles.previewTitle}>“{preview.title}”</span>
298:             <span style={styles.previewTime}>
299:               {formatClock(preview.startAt)}
300:               {preview.endAt ? `–${formatClock(preview.endAt)}` : ''}
301:             </span>
302:             {preview.tagPaths.map((path) => (
303:               <span key={`preview-tag-${path}`} style={styles.tagChip}>
304:                 #{path}
305:               </span>
306:             ))}
307:             {preview.peopleNames.map((name) => (
308:               <span key={`preview-person-${name}`} style={styles.personChip}>
309:                 @{name}
310:               </span>
311:             ))}
312:           </div>
313:         )}
314:         {quickError && <div style={styles.quickError}>{quickError}</div>}
315:       </section>
316: 
317:       <div style={styles.columns}>
318:         <section style={styles.column}>
319:           <h2 style={styles.cardTitle}>EVENTS ({events.length})</h2>
320:           {events.length === 0 ? (
321:             <p style={styles.empty}>No events logged. Try “read #reading for 45m”.</p>
322:           ) : (
323:             events.map((event) => {
324:               const paths = tagsForEvent(event.id);
325:               return (
326:                 <div key={event.id} style={styles.eventRow}>
327:                   <div style={styles.eventRowTime}>
328:                     {formatClock(event.startAt)}
329:                     <div style={styles.eventRowTimeEnd}>
330:                       {event.endAt ? formatClock(event.endAt) : 'point'}
331:                     </div>
332:                   </div>
333:                   <div style={styles.eventRowBody}>
334:                     <div style={styles.eventRowTitle}>{event.title}</div>
335:                     <div style={styles.eventRowMeta}>
336:                       <span style={styles.sourceBadge}>{event.source}</span>
337:                       {paths.map((path) => (
338:                         <span key={`event-tag-${event.id}-${path}`} style={styles.tagChip}>
339:                           #{path}
340:                         </span>
341:                       ))}
342:                     </div>
343:                   </div>
344:                 </div>
345:               );
346:             })
347:           )}
348:         </section>
349: 
350:         <section style={styles.column}>
351:           <h2 style={styles.cardTitle}>JOURNAL</h2>
352:           {journalEntries.length === 0 ? (
353:             <p style={styles.empty}>No reflection yet. The evening review will prompt you.</p>
354:           ) : (
355:             journalEntries.map((entry) => (
356:               <div key={entry.id} style={styles.journalCard}>
357:                 <p style={styles.journalBody}>{entry.body}</p>
358:                 <div style={styles.journalMeta}>{formatClock(entry.writtenAt)}</div>
359:               </div>
360:             ))
361:           )}
362:         </section>
363:       </div>
364: 
365:       <section style={styles.card}>
366:         <h2 style={styles.cardTitle}>MARKERS ({markers.length})</h2>
367:         {markers.length === 0 ? (
368:           <p style={styles.empty}>No markers recorded for this day yet.</p>
369:         ) : (
370:           markers.map((marker) => <MarkerItem key={marker.id} marker={marker} />)
371:         )}
372:       </section>
373:     </div>
374:   );
375: };
