107: function zonedTimeToUtc(
108:   year: number,
109:   month: number,
110:   day: number,
111:   hours: number,
112:   minutes: number,
113:   seconds: number,
114:   timeZone: string
115: ): Date {
116:   const guess = Date.UTC(year, month - 1, day, hours, minutes, seconds);
117:   let offset = getTimeZoneOffsetMs(new Date(guess), timeZone);
118:   let result = guess - offset;
119:   offset = getTimeZoneOffsetMs(new Date(result), timeZone);
120:   result = guess - offset;
121:   return new Date(result);
