166: function parseDurationMs(raw: string): number | null {
167:   const match = /^P(?:(\d+)W)?(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$/.exec(
168:     raw.trim().toUpperCase()
169:   );
170:   if (!match) return null;
171: 
172:   const weeks = Number(match[1] ?? 0);
173:   const days = Number(match[2] ?? 0);
174:   const hours = Number(match[3] ?? 0);
175:   const minutes = Number(match[4] ?? 0);
176:   const seconds = Number(match[5] ?? 0);
177:   const total =
178:     ((weeks * 7 + days) * 24 * 60 * 60 + hours * 60 * 60 + minutes * 60 + seconds) * 1000;
179: 
180:   return total > 0 ? total : null;
181: }
