183: function stableHash(value: string): string {
184:   let hash = 0x811c9dc5;
185:   for (let index = 0; index < value.length; index++) {
186:     hash ^= value.charCodeAt(index);
187:     hash = Math.imul(hash, 0x01000193) >>> 0;
