201: function parseEvent(lines: string[]): CalendarEvent | null {
202:   const properties: IcsProperty[] = [];
203: 
204:   for (const line of lines) {
205:     const trimmed = line.trim();
206:     if (!trimmed) continue;
207:     const upper = trimmed.toUpperCase();
208:     if (upper.startsWith('BEGIN:VALARM') || upper.startsWith('BEGIN:VTIMEZONE')) continue;
209:     if (upper.startsWith('END:VALARM') || upper.startsWith('END:VTIMEZONE')) continue;
210: 
211:     const property = parseProperty(line);
212:     if (property) properties.push(property);
213:   }
214: 
215:   const find = (name: string): IcsProperty | undefined =>
216:     properties.find((property) => property.name === name);
217: 
218:   const startProperty = find('DTSTART');
219:   if (!startProperty) return null;
220:   const start = parseIcsDate(startProperty.value, startProperty.params);
221:   if (!start) return null;
222: 
223:   const title = unescapeIcsText(find('SUMMARY')?.value ?? '').trim() || '(untitled event)';
224:   const description = find('DESCRIPTION')?.value;
225:   const location = find('LOCATION')?.value;
226:   const organizerProperty = find('ORGANIZER');
227:   const organizer = organizerProperty
228:     ? attendeeLabel(organizerProperty)
229:     : undefined;
230:   const attendees = properties
231:     .filter((property) => property.name === 'ATTENDEE')
232:     .map(attendeeLabel)
233:     .filter((value) => value.length > 0);
234: 
235:   let endAt: Date | undefined;
236:   const endProperty = find('DTEND');
237:   if (endProperty) {
238:     const end = parseIcsDate(endProperty.value, endProperty.params);
239:     endAt = end?.date;
240:   } else {
241:     const durationProperty = find('DURATION');
242:     if (durationProperty) {
243:       const durationMs = parseDurationMs(durationProperty.value);
244:       if (durationMs !== null) endAt = new Date(start.date.getTime() + durationMs);
245:     }
246:   }
247: 
248:   if (!endAt && start.allDay) {
249:     endAt = new Date(start.date.getTime() + 24 * 60 * 60 * 1000 - 1);
250:   }
251:   if (endAt && endAt.getTime() <= start.date.getTime()) {
252:     endAt = undefined;
253:   }
254: 
255:   const uid = find('UID')?.value.trim();
256:   const externalId =
257:     uid && uid.length > 0
258:       ? uid
259:       : `${start.date.toISOString()}|${title}|${attendees.join(',')}`;
260: 
261:   return {
262:     externalId,
263:     title,
264:     startAt: start.date.toISOString(),
265:     endAt: endAt?.toISOString(),
266:     allDay: start.allDay,
267:     timezone: startProperty.params.TZID,
268:     description: description ? unescapeIcsText(description) : undefined,
269:     location: location ? unescapeIcsText(location) : undefined,
270:     organizer,
271:     attendees,
272:     recurrenceRule: find('RRULE')?.value,
273:   };
274: }
