276: /**
277:  * Parses an ICS calendar into events. Never throws: malformed VEVENT blocks are
278:  * reported in `skipped` and valid blocks continue to be imported. Recurring
279:  * events import their first occurrence and retain the RRULE for later expansion.
280:  */
281: export function parseIcsCalendar(text: string): CalendarParseResult {
282:   const result: CalendarParseResult = { events: [], skipped: [] };
283:   if (typeof text !== 'string' || text.trim().length === 0) return result;
284: 
285:   const unfolded = text
286:     .replace(/\r\n/g, '\n')
287:     .replace(/\r/g, '\n')
288:     .replace(/\n[ \t]/g, '');
289: 
290:   const lines = unfolded.split('\n');
291:   let current: string[] | null = null;
292:   let inAlarm = false;
293: 
294:   for (const line of lines) {
295:     const trimmed = line.trim();
296:     const upper = trimmed.toUpperCase();
297: 
298:     if (current === null) {
299:       if (upper === 'BEGIN:VEVENT') current = [];
300:       continue;
301:     }
302: 
303:     if (upper === 'END:VEVENT') {
304:       try {
305:         const event = parseEvent(current);
306:         if (event) result.events.push(event);
307:         else result.skipped.push({ reason: 'VEVENT has no valid DTSTART' });
308:       } catch (error) {
309:         result.skipped.push({
310:           reason: error instanceof Error ? error.message : String(error),
311:         });
312:       }
313:       current = null;
314:       inAlarm = false;
315:       continue;
316:     }
317: 
318:     if (upper === 'BEGIN:VALARM') {
319:       inAlarm = true;
320:       continue;
321:     }
322:     if (upper === 'END:VALARM') {
323:       inAlarm = false;
324:       continue;
325:     }
326:     if (!inAlarm) current.push(line);
327:   }
328: 
329:   return result;
330: }
