332: function composeNotes(event: CalendarEvent): string | undefined {
333:   const parts: string[] = [];
334:   if (event.location) parts.push(`Location: ${event.location}`);
335:   if (event.organizer) parts.push(`Organizer: ${event.organizer}`);
336:   if (event.attendees.length > 0) parts.push(`Attendees: ${event.attendees.join(', ')}`);
337:   if (event.description) parts.push(event.description);
338:   if (event.recurrenceRule) parts.push(`Recurrence: ${event.recurrenceRule}`);
339:   return parts.length > 0 ? parts.join('\n') : undefined;
340: }
