342: /**
343:  * Converts parsed calendar events into deterministic pending Suggestions.
344:  * Calendar times are planned, so precision is `approx` until the user accepts.
345:  */
346: export function calendarEventsToSuggestions(
347:   events: CalendarEvent[],
348:   options: CalendarSuggestionOptions = {}
349: ): Suggestion[] {
350:   const now = options.now ?? new Date();
351:   const confidence = options.confidence ?? 0.9;
352:   const seen = new Set<string>();
353:   const suggestions: Suggestion[] = [];
354: 
355:   for (const event of events) {
356:     if (seen.has(event.externalId)) continue;
357:     seen.add(event.externalId);
358: 
359:     try {
360:       suggestions.push(
361:         buildSuggestion(
362:           {
363:             source: 'calendar',
364:             confidence,
365:             externalId: event.externalId,
366:             proposed: {
367:               title: event.title,
368:               startAt: event.startAt,
369:               endAt: event.endAt,
370:               startPrecision: 'approx',
371:               endPrecision: event.endAt ? 'approx' : 'unknown',
372:               notes: composeNotes(event),
373:             },
374:           },
375:           { id: calendarSuggestionId(event.externalId), now }
376:         )
377:       );
378:     } catch {
379:       // A malformed calendar row must never abort the rest of the import.
380:     }
381:   }
382: 
383:   return suggestions;
384: }

