export interface BenchmarkDocument {
  timestamp?: string;
  environment?: Record<string, unknown>;
  metrics: Record<string, number>;
  passedTargets?: Record<string, boolean>;
}

export interface Regression {
  name: string;
  baselineMs: number;
  currentMs: number;
  ratio: number;
}

/** A metric may not be more than this multiple of the baseline value. */
export const MAX_REGRESSION_FACTOR = 3;

/**
 * Compares two benchmark documents metric by metric. Only metrics that are
 * present as positive numbers in both documents are compared, so adding a new
 * metric does not fail against an older baseline.
 */
export function compareBenchmarks(
  current: BenchmarkDocument,
  baseline: BenchmarkDocument,
  factor: number = MAX_REGRESSION_FACTOR
): Regression[] {
  const regressions: Regression[] = [];

  for (const [name, baselineMs] of Object.entries(baseline.metrics)) {
    const currentMs = current.metrics[name];
    if (typeof currentMs !== 'number' || !Number.isFinite(currentMs)) continue;
    if (typeof baselineMs !== 'number' || !Number.isFinite(baselineMs) || baselineMs <= 0) continue;

    const ratio = currentMs / baselineMs;
    if (ratio > factor) {
      regressions.push({ name, baselineMs, currentMs, ratio });
    }
  }

  return regressions.sort((a, b) => b.ratio - a.ratio);
}

export function formatRegression(regression: Regression, factor: number = MAX_REGRESSION_FACTOR): string {
  return (
    `${regression.name}: ${regression.currentMs.toFixed(3)} ms is ` +
    `${regression.ratio.toFixed(2)}x the baseline of ${regression.baselineMs.toFixed(3)} ms ` +
    `(limit ${factor}x)`
  );
}

import * as os from 'node:os';
import * as path from 'node:path';

export interface BenchOptions {
  outputPath: string;
  hostLabel: string;
  comparePath?: string;
}

export const DEFAULT_OUTPUT = path.join('docs', 'benchmarks', 'bench-current.json');

export const USAGE = `Usage: node dist/index.js [options]

Runs the Life Logger benchmark suite and writes a JSON result file.

Options:
  --output <path>       Where to write the result JSON
                        (default: ${DEFAULT_OUTPUT})
  --host-label <label>  Label recorded in the result, for example "pc" or "server"
                        (default: $HOST_LABEL or the machine hostname)
  --compare <path>      Read a baseline JSON and fail if any metric is more
                        than ${3}x slower than that baseline
  --help                Show this message
`;

function readValue(argv: string[], index: number, name: string): { value: string; next: number } {
  const inline = argv[index];
  const equals = inline.indexOf('=');
  if (equals !== -1) {
    const value = inline.slice(equals + 1);
    if (value.length === 0) throw new Error(`Missing value for ${name}`);
    return { value, next: index };
  }

  const value = argv[index + 1];
  if (value === undefined || value.startsWith('--')) {
    throw new Error(`Missing value for ${name}`);
  }
  return { value, next: index + 1 };
}

export function parseArgs(
  argv: string[],
  env: NodeJS.ProcessEnv = process.env,
  hostname: string = os.hostname()
): BenchOptions {
  const options: BenchOptions = {
    outputPath: DEFAULT_OUTPUT,
    hostLabel: env.HOST_LABEL?.trim() || hostname,
  };

  for (let index = 0; index < argv.length; index++) {
    const arg = argv[index];

    if (arg === '--help' || arg === '-h') {
      throw new HelpRequested();
    } else if (arg === '--output' || arg.startsWith('--output=')) {
      const parsed = readValue(argv, index, '--output');
      options.outputPath = parsed.value;
      index = parsed.next;
    } else if (arg === '--host-label' || arg.startsWith('--host-label=')) {
      const parsed = readValue(argv, index, '--host-label');
      options.hostLabel = parsed.value;
      index = parsed.next;
    } else if (arg === '--compare' || arg.startsWith('--compare=')) {
      const parsed = readValue(argv, index, '--compare');
      options.comparePath = parsed.value;
      index = parsed.next;
    } else {
      throw new Error(`Unknown argument: ${arg}`);
    }
  }

  return options;
}

export class HelpRequested extends Error {
  constructor() {
    super('Help requested');
    this.name = 'HelpRequested';
  }
}

