import * as fs from 'node:fs';
import * as path from 'node:path';

const root = process.cwd();
const prefix = 'file:///C:/Users/thema/test/you';
const pattern = /file:\/\/\/C:\/Users\/thema\/test\/you(?:\/([^\s)#)]*))?(#[^\s)]*)?/g;

function toRelative(filePath) {
  const dir = path.dirname(path.resolve(root, filePath)).replace(/\\/g, '/');
  const relative = path.relative(dir, root).replace(/\\/g, '/');
  return relative.length === 0 ? '.' : relative;
}

function rewrite(filePath) {
  const absolute = path.resolve(root, filePath);
  const original = fs.readFileSync(absolute, 'utf8');
  const dir = path.dirname(absolute).replace(/\\/g, '/');
  const updated = original.replace(pattern, (_match, rel, anchor) => {
    let target = root;
    if (rel) {
      target = path.resolve(root, decodeURIComponent(rel));
    }
    let relative = path.relative(dir, target).replace(/\\/g, '/');
    if (relative.length === 0) relative = '.';
    if (!relative.startsWith('.')) relative = `./${relative}`;
    relative = relative
      .replace(/%/g, '%25')
      .replace(/ /g, '%20')
      .replace(/\(/g, '%28')
      .replace(/\)/g, '%29');
    return relative + (anchor && anchor.startsWith('#') ? anchor : '');
  });

  if (updated !== original) {
    fs.writeFileSync(absolute, updated, 'utf8');
  }
}

const entries = fs.readdirSync(root, { recursive: true, withFileTypes: true });
for (const entry of entries) {
  if (!entry.isFile() || !entry.name.endsWith('.md')) continue;
  const parent = entry.parentPath ?? entry.path;
  const relative = path.relative(root, path.join(parent, entry.name));
  rewrite(relative);
}

